// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        uint256 seedBank = 1 ether;
        vm.deal(address(c), seedBank);

        uint256 withdrawAmount = amount % (seedBank + 1);

        vm.prank(caller);
        bool ok;
        try c.withdraw(withdrawAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(address(c).balance == seedBank == true || ok == false);
    }
}
